package com.vandorlabs.neoforge.builders;

import com.vandorlabs.neoforge.credentials.*;
import com.vandorlabs.neoforge.screen.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.nbt.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.item.*;
import net.minecraft.world.item.component.CustomData;
import java.util.*;

/** Real native policy, strict template codec, Source metadata migration and public Catalog projection. */
public final class NativeBlockRecipeChecks {
 private static int checks;
 public static void run(ServerLevel world){
  for(var item:new Item[]{Items.STONE,Items.GLASS,Items.FURNACE,Items.OAK_SLAB,Items.OAK_TRAPDOOR,Items.DIRT,Items.OAK_PLANKS,Items.OAK_STAIRS,Items.DISPENSER,Items.DROPPER,Items.BARREL})need(NativeBlockRecipeData.eligible(new ItemStack(item)),"eligible manufactured/regular vanilla "+item);
  for(var item:new Item[]{Items.CHEST,Items.OAK_LOG,Items.OAK_LEAVES,Items.OAK_DOOR,Items.RED_BED,Items.WHEAT_SEEDS,Items.CACTUS,Items.PUMPKIN,Items.CARVED_PUMPKIN,Items.JACK_O_LANTERN,Items.LEVER,Items.SHULKER_BOX,Items.OAK_FENCE})need(!NativeBlockRecipeData.eligible(new ItemStack(item)),"ineligible organic/owner/nonregular "+item);
  for(String id:List.of("programmable_block","programmable_slab","programmable_screen","programmable_diagonal_screen","synthesis_tower_core","standalone_dish_core","standalone_antenna_core","programmable_ramp")){var key=ResourceLocation.fromNamespaceAndPath("vandorlabs",id);if(BuiltInRegistries.ITEM.containsKey(key))need(NativeBlockRecipeData.eligible(new ItemStack(BuiltInRegistries.ITEM.get(key))),"eligible native "+id);}
  var chip=NativeCredentialItems.dataChip(2);chip.set(DataComponents.CUSTOM_NAME,net.minecraft.network.chat.Component.literal("Old Anvil Name"));var privateData=new CompoundTag();privateData.putString("PrivateOwnerNote","retained only on chip");chip.set(DataComponents.CUSTOM_DATA,CustomData.of(privateData));var source=new ItemStack(Items.OAK_SLAB,3);NativeBlockRecipeData.write(chip,source,world.registryAccess());need(source.getCount()==3,"programming stages template without consuming source");need(!chip.getHoverName().getString().contains("Old Anvil Name")&&chip.getHoverName().getString().contains(source.getHoverName().getString()),"scanned Catalog label replaces previous anvil name");var decoded=NativeBlockRecipeData.read(chip,world.registryAccess());need(decoded.is(Items.OAK_SLAB)&&decoded.getCount()==1&&ItemStack.matches(decoded,NativeBlockRecipeData.read(chip)),"explicit/built-in registry template reads agree");need(NativeCredentialItems.company(chip)==2&&chip.get(DataComponents.CUSTOM_DATA).copyTag().getString("PrivateOwnerNote").equals("retained only on chip"),"Catalog programming preserves company and opaque credential fields");
  var saved=ItemStack.parse(world.registryAccess(),chip.save(world.registryAccess())).orElseThrow();need(ItemStack.matches(chip,saved)&&ItemStack.matches(decoded,NativeBlockRecipeData.read(saved,world.registryAccess())),"Catalog item save roundtrip");var returned=NativeBlockRecipeData.read(chip);returned.setCount(7);need(NativeBlockRecipeData.read(chip).getCount()==1,"template result is defensive copy");
  var projection=NativeBlockRecipeData.publicData(chip);need(projection!=null&&projection.getAllKeys().equals(Set.of("Version","Stack","State"))&&!projection.toString().contains("PrivateOwnerNote"),"safe public template excludes chip owner data");var raw=new CompoundTag();raw.put("InsertedToken",chip.save(world.registryAccess()));var reader=NativeEmbeddedChipReader.storage(raw,world.registryAccess());var view=NativeScreenChipView.of(reader,world.getGameTime(),0);need(view.catalog()&&NativeScreenChipView.read(view.write()).catalogItem().is(Items.OAK_SLAB)&&!view.write().toString().contains("PrivateOwnerNote"),"actual Catalog Screen reader public projection roundtrip");
  for(int fault=0;fault<7;fault++){var bad=chip.copy();var root=bad.get(DataComponents.CUSTOM_DATA).copyTag();var template=root.getCompound("CatalogBlock");switch(fault){case 0->template.putInt("Version",2);case 1->template.getCompound("Stack").putInt("count",2);case 2->template.getCompound("State").putString("Name","minecraft:diamond_block");case 3->template.putString("FutureOwner","secret");case 4->template.getCompound("Stack").put("ForgeCaps",new CompoundTag());case 5->root.putString("CatalogName","x".repeat(41));case 6->root.getCompound("Catalog").getCompound("Designs").put("synthesis_tower",new ListTag());}bad.set(DataComponents.CUSTOM_DATA,CustomData.of(root));var exact=bad.copy();need(NativeBlockRecipeData.read(bad,world.registryAccess()).isEmpty()&&ItemStack.matches(exact,bad),"invalid template retained fault="+fault);}
  for(var item:new Item[]{Items.DISPENSER,Items.DROPPER,Items.BARREL}){var occupied=new ItemStack(item);occupied.set(DataComponents.CONTAINER,net.minecraft.world.item.component.ItemContainerContents.fromItems(List.of(new ItemStack(Items.DIAMOND))));need(!NativeBlockRecipeData.eligible(occupied),"regular container with contents component denied "+item);var configured=new ItemStack(item);var tile=new CompoundTag();var contents=new ListTag();var entry=new CompoundTag();entry.putInt("Slot",0);entry.putString("id","minecraft:diamond");entry.putInt("count",1);contents.add(entry);tile.put("Items",contents);configured.set(DataComponents.BLOCK_ENTITY_DATA,CustomData.of(tile));need(!NativeBlockRecipeData.eligible(configured),"regular container with tile ownership NBT denied "+item);}
  var named=new ItemStack(Items.STONE);var extra=new CompoundTag();extra.putString("Inventory","forbidden");named.set(DataComponents.CUSTOM_DATA,CustomData.of(extra));need(!NativeBlockRecipeData.eligible(named),"vanilla opaque component denied");
  var oldWool=legacy("minecraft:wool",5);var woolState=new CompoundTag();woolState.putString("Name","minecraft:wool");var woolProperties=new CompoundTag();woolProperties.putString("color","lime");woolState.put("Properties",woolProperties);var imported=legacyChip(chip,oldWool,woolState);need(NativeBlockRecipeData.read(imported,world.registryAccess()).is(Items.LIME_WOOL),"released wool metadata5 DFU migrates exact item/state");
  var key=ResourceLocation.parse("vandorlabs:programmable_block");if(BuiltInRegistries.ITEM.containsKey(key)){var old=legacy(key.toString(),2);var appearance=new CompoundTag();appearance.putInt("MainTexture",3);var envelope=new CompoundTag();envelope.put("BlockEntityTag",appearance);old.put("tag",envelope);var state=net.minecraft.nbt.NbtUtils.writeBlockState(((BlockItem)BuiltInRegistries.ITEM.get(key)).getBlock().defaultBlockState());var migrated=NativeBlockRecipeData.read(legacyChip(chip,old,state),world.registryAccess());need(!migrated.isEmpty()&&migrated.get(DataComponents.CUSTOM_DATA).copyTag().getCompound("BlockEntityTag").getInt("MainTexture")==3,"released configured native appearance migrates narrowly");var converted=chip.copy();NativeBlockRecipeData.write(converted,migrated,world.registryAccess());need(ItemStack.matches(NativeBlockRecipeData.read(converted),NativeBlockRecipeData.read(converted,world.registryAccess())),"configured native registered components use built-in public lookup correctly");appearance.put("Items",new ListTag());old.getCompound("tag").put("BlockEntityTag",appearance);need(NativeBlockRecipeData.read(legacyChip(chip,old,state),world.registryAccess()).isEmpty(),"released tile inventory never becomes template");}
  System.out.println("[vandorlabs][block-recipe] PASS checks="+checks+" policy/template/privateProjection/legacyVanillaDFU/nativeAppearance/ownershipRefusal");
 }
 private static CompoundTag legacy(String id,int meta){var raw=new CompoundTag();raw.putString("id",id);raw.putByte("Count",(byte)1);raw.putShort("Damage",(short)meta);return raw;}
 private static ItemStack legacyChip(ItemStack base,CompoundTag stack,CompoundTag state){var chip=base.copy();var root=chip.get(DataComponents.CUSTOM_DATA).copyTag();var template=new CompoundTag();template.putInt("Version",1);template.put("Stack",stack.copy());template.put("State",state.copy());root.put("CatalogBlock",template);chip.set(DataComponents.CUSTOM_DATA,CustomData.of(root));return chip;}
 private static void need(boolean v,String m){checks++;if(!v)throw new AssertionError(m);}
 private NativeBlockRecipeChecks(){}
}
